package com.nexus.service;
import com.nexus.data.*; import com.nexus.domain.*; import com.nexus.domain.Rules.*; import com.nexus.strategy.*; import com.nexus.event.*; import com.nexus.web.ApiErrors.Missing; import com.nexus.web.Views; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.context.ApplicationEventPublisher; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional public class IncidentService{
 private final IncidentRepository incidents;private final AccountRepository accounts;private final ITServiceRepository services;private final CategoryRepository categories;private final SlaPolicyRepository policies;private final SettingRepository settings;private final AuditRepository audit;private final ApplicationEventPublisher events;private final Clock clock;private final ObjectMapper mapper;
 public IncidentService(IncidentRepository i,AccountRepository a,ITServiceRepository s,CategoryRepository c,SlaPolicyRepository p,SettingRepository set,AuditRepository au,ApplicationEventPublisher ev,Clock clock,ObjectMapper m){incidents=i;accounts=a;services=s;categories=c;policies=p;settings=set;audit=au;events=ev;this.clock=clock;mapper=m;}
 public IncidentRepository incidents(){return incidents;}
 public ITServiceRepository services(){return services;}
 public CategoryRepository categories(){return categories;}
 public SlaPolicyRepository policies(){return policies;}
 public SettingRepository settings(){return settings;}
 public AuditRepository audit(){return audit;}
 public Incident get(long id){return incidents.findById(id).orElseThrow(()->new Missing("Incident not found"));}private Incident lock(long id){return incidents.locked(id).orElseThrow(()->new Missing("Incident not found"));}
 public ITService service(long id){return services.findById(id).orElseThrow(()->new Missing("Service not found"));}public Category category(long id){return categories.findById(id).orElseThrow(()->new Missing("Category not found"));}
 public boolean canSee(Account a,Incident i){return a.role()==Role.ADMINISTRATOR||Objects.equals(i.reporter.id,a.id)||i.technician!=null&&Objects.equals(i.technician.id,a.id);}
 public void visible(Account a,Incident i){if(!canSee(a,i))throw new AccessDeniedException("Incident access denied");}
 private void require(boolean ok){if(!ok)throw new AccessDeniedException("Operation forbidden");}
 public List<Incident> scoped(Account a){return (a.role()==Role.ADMINISTRATOR?incidents.findAll():incidents.findVisibleV5(a.id)).stream().filter(i->canSee(a,i)).sorted(Comparator.comparing((Incident i)->i.priority).thenComparing(i->i.createdAt,Comparator.reverseOrder())).toList();}
 public Target target(ITService s,Priority p){return policies.findById(SlaPolicy.key(s.id,p)).or(()->policies.findById(SlaPolicy.key(null,p))).orElseThrow(()->new IllegalStateException("SLA policy missing")).target();}
 public String strategy(){return settings.findById("assignment").map(s->s.settingValue).orElse("SKILL");}
 public AssignmentStrategy.Decision decision(Category category,String strategy,Long excludeIncident){AssignmentStrategy algo=switch(strategy){case "SKILL"->new SkillBasedAssignment();case "LOAD"->new LoadBasedAssignment();default->throw new IllegalArgumentException("Unknown strategy");};Map<Long,Integer> workloads=new HashMap<>();for(Incident i:incidents.findAll())if(i.status().active()&&i.technician!=null&&!Objects.equals(i.id,excludeIncident))workloads.merge(i.technician.id,1,Integer::sum);return algo.decide(accounts.findAll().stream().filter(a->a instanceof Technician).map(a->(Technician)a).map(t->new AssignmentStrategy.Candidate(t.id,t.name,t.skills.getOrDefault(category.name,0),workloads.getOrDefault(t.id,0),t.capacity,t.available&&t.enabled)).toList());}
 private Set<Long> adminIds(){Set<Long> ids=new HashSet<>();for(Account a:accounts.findAll())if(a.role()==Role.ADMINISTRATOR&&a.enabled)ids.add(a.id);return ids;}
 private void emit(Incident i,String actor,String action,Status old,String detail,boolean priv,boolean notify){Set<Long> to=new HashSet<>();if(notify){to.add(i.reporter.id);if(i.technician!=null)to.add(i.technician.id);if(action.equals("ESCALATED")||action.equals("NO_TECHNICIAN")||action.contains("BREACH"))to.addAll(adminIds());}events.publishEvent(new IncidentEvent(i.id,clock.instant(),actor,action,old==null?null:old.name(),i.status().name(),detail,priv,to));}
 public Map<String,Object> preview(Account a,long serviceId,long categoryId,int impact,int urgency,String text){ITService s=service(serviceId);Category c=category(categoryId);Priority p=Rules.priority(impact,urgency,s.criticality);return Views.map("score",Rules.score(impact,urgency,s.criticality),"priority",p,"target",target(s,p),"duplicates",matches(a,s,c,text,null));}
 private List<Map<String,Object>> matches(Account a,ITService s,Category c,String text,Long exclude){return incidents.findAll().stream().filter(i->!Objects.equals(i.id,exclude)&&i.status().active()&&i.service.id.equals(s.id)&&i.category.id.equals(c.id)&&i.createdAt.isAfter(clock.instant().minus(Duration.ofDays(7)))&&canSee(a,i)).map(i->Views.map("id",i.id,"title",i.title,"similarity",Rules.similarity(text,i.title+" "+i.description))).filter(m->(double)m.get("similarity")>=.35).sorted(Comparator.comparingDouble(m->-(double)m.get("similarity"))).toList();}
 public Incident create(Account a,String title,String description,long serviceId,long categoryId,int impact,int urgency){require(a.role()==Role.EMPLOYEE);ITService s=service(serviceId);Category c=category(categoryId);Priority p=Rules.priority(impact,urgency,s.criticality);Incident i=incidents.save(new Incident(title,description,a,s,c,impact,urgency,clock.instant(),target(s,p)));emit(i,a.name,"CREATED",null,title,false,true);i.move(Status.CLASSIFIED);emit(i,"SYSTEM","CLASSIFIED",Status.NEW,c.name,false,false);emit(i,"SYSTEM","PRIORITY_CALCULATED",null,impact+" × "+urgency+" × "+s.criticality+" = "+p,false,false);autoAssign(i);return i;}
 private void autoAssign(Incident i){settings.locked("assignment");var d=decision(i.category,strategy(),i.id);try{i.assignmentEvidence=mapper.writeValueAsString(d);}catch(Exception e){throw new IllegalStateException("Assignment evidence serialization failed");}if(d.selected()==null){emit(i,"SYSTEM","NO_TECHNICIAN",null,"No qualified available technician below capacity",false,true);return;}Status old=i.status();i.assign((Technician)accounts.findById(d.selected()).orElseThrow());emit(i,"SYSTEM","ASSIGNED",old,"Selected "+i.technician.name+" via "+d.strategy(),false,true);}
 public Incident action(Account a,long id,String action,String text,Integer rating,Long technicianId,Long relatedId){Incident i=lock(id);visible(a,i);Status old=i.status();boolean tech=a.role()==Role.TECHNICIAN&&i.technician!=null&&a.id.equals(i.technician.id);boolean reporter=a.role()==Role.EMPLOYEE&&a.id.equals(i.reporter.id);boolean admin=a.role()==Role.ADMINISTRATOR;String detail=text==null?"":text.trim();if(detail.length()>8000)throw new IllegalArgumentException("Text too long");if(old==Status.CLOSED)throw new IllegalStateException("Incident is closed");switch(action){
 case "acknowledge"->{require(tech);i.acknowledge(clock.instant());}
 case "start"->{require(tech);i.move(Status.IN_PROGRESS);}
 case "resolve"->{require(tech);i.resolve(detail,clock.instant());}
 case "verify"->{require(reporter);if(detail.length()>2000)throw new IllegalArgumentException("Feedback max 2000 characters");i.verify(detail,rating,clock.instant());}
 case "close"->{require(reporter||admin);i.close(clock.instant());}
 case "reopen"->{require(reporter);i.reopen();}
 case "note","request-info","private-note"->{require(tech||reporter||admin);if(action.equals("private-note")||action.equals("request-info"))require(tech||admin);if(detail.isBlank())throw new IllegalArgumentException("Message required");emit(i,a.name,action.toUpperCase(Locale.ROOT),old,detail,action.equals("private-note"),!action.equals("private-note"));return i;}
 case "assign"->{require(admin);settings.locked("assignment");if(technicianId==null){autoAssign(i);return i;}var d=decision(i.category,strategy(),i.id);if(d.ranked().stream().noneMatch(c->c.id()==technicianId))throw new IllegalArgumentException("Technician is not eligible");i.assign((Technician)accounts.findById(technicianId).orElseThrow());detail="Manual assignment to "+i.technician.name;}
 case "link"->{require(tech||admin);if(relatedId==null||relatedId==id)throw new IllegalArgumentException("Choose another incident");Incident other=get(relatedId);visible(a,other);i.related.add(other.id);detail="Linked INC-"+other.id;}
 default->throw new IllegalArgumentException("Unknown action");}emit(i,a.name,action.toUpperCase(Locale.ROOT),old,detail,false,true);evaluate(i);return i;}
 public List<Audit> timeline(Account a,long id){Incident i=get(id);visible(a,i);return audit.findByIncidentIdOrderByIdAsc(id).stream().filter(e->!e.privateEntry||a.role()!=Role.EMPLOYEE).toList();}
 public List<Map<String,Object>> duplicates(Account a,long id){Incident i=get(id);visible(a,i);return matches(a,i.service,i.category,i.title+" "+i.description,id);}
 private void evaluate(Incident i){Instant now=clock.instant();Sla r=Rules.sla(now,i.responseDue,i.acknowledgedAt,i.warningMinutes),s=Rules.sla(now,i.resolutionDue,i.resolvedAt,i.warningMinutes);if(r==Sla.WARNING&&!i.responseWarning){i.responseWarning=true;emit(i,"SYSTEM","RESPONSE_WARNING",null,"Response deadline approaching",false,true);}if(s==Sla.WARNING&&!i.resolutionWarning){i.resolutionWarning=true;emit(i,"SYSTEM","RESOLUTION_WARNING",null,"Resolution deadline approaching",false,true);}if(r==Sla.BREACHED&&!i.responseBreach){i.responseBreach=true;emit(i,"SYSTEM","RESPONSE_BREACH",null,"Response SLA breached",false,true);}if(s==Sla.BREACHED&&!i.resolutionBreach){i.resolutionBreach=true;emit(i,"SYSTEM","RESOLUTION_BREACH",null,"Resolution SLA breached",false,true);}if(i.priority==Priority.P1&&r==Sla.BREACHED&&!i.escalated){i.escalated=true;emit(i,"SYSTEM","ESCALATED",null,"P1 response SLA missed; administrator alerted",false,true);}}
 public void monitor(long id){evaluate(lock(id));}
}
